INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2772738, 387970, 39349, '<td valign="top">Very tasteful nude study. I really like the golden tones and light you''ve captured here. Two things hurt this shot technically IMHO, first the towel draws your eye down and away from the beautiful female lines of the body and second the sheet behind her. Still this is a beautiful image that you should be proud of. I still want to impress on you how much I like the lighting in this shot, it''s AWESOME!</td>', 'Very tasteful nude study. I really like the golden tones and light you''ve captured here. Two things hurt this shot technically IMHO, first the towel draws your eye down and away from the beautiful female lines of the body and second the sheet behind her. Still this is a beautiful image that you should be proud of. I still want to impress on you how much I like the lighting in this shot, it''s AWESOME!', '2006-08-30 02:40:38.000000', NULL, 1),
(2772749, 384445, 39349, '<td valign="top">Overall, a bit flat for b/w. Clouds are too burned out for my taste, still you''ve met the challenge by creating a silhouette with the building against the cloudy sky. 5 from me.</td>', 'Overall, a bit flat for b/w. Clouds are too burned out for my taste, still you''ve met the challenge by creating a silhouette with the building against the cloudy sky. 5 from me.', '2006-08-30 02:42:25.000000', NULL, 1),
