(2779837, 386735, 57202, '<td valign="top">AWESOME idea for a shot!  Great colors, great silhouette. :)</td>', 'AWESOME idea for a shot!  Great colors, great silhouette. :)', '2006-08-31 20:31:23.000000', NULL, 1),
(2779859, 387729, 48902, '<td valign="top">Hope this one wins, captures so much, youth, adventure, the father watching his children play, my favorite in this challange</td>', 'Hope this one wins, captures so much, youth, adventure, the father watching his children play, my favorite in this challange', '2006-08-31 20:41:55.000000', NULL, 1),
(2779888, 386435, 57320, '<td valign="top">The problem with this, is that I can see som of the model''s features, This is a <b>silhouette</b>! You can fix that with a touch of contrast</td>', 'The problem with this, is that I can see som of the model''s features, This is a silhouette! You can fix that with a touch of contrast', '2006-08-31 20:55:07.000000', NULL, 1),
