(2779924, 386725, 5885, '<td valign="top">Me likes!</td>', 'Me likes!', '2006-08-31 21:12:39.000000', NULL, 1),
(2779927, 385098, 5885, '<td valign="top">Comes across as just an under-exposed portrait to me.</td>', 'Comes across as just an under-exposed portrait to me.', '2006-08-31 21:13:28.000000', NULL, 1),
(2779929, 387949, 5885, '<td valign="top">Nice work here... I''ll be waiting to see the setup. I''m guessing glass :-)</td>', 'Nice work here... I''ll be waiting to see the setup. I''m guessing glass :-)', '2006-08-31 21:14:15.000000', NULL, 1),
