(2790032, 386623, 61890, '<td valign="top">very nice</td>', 'very nice', '2006-09-02 21:18:45.000000', NULL, 1),
(2790550, 385155, 57726, '<td valign="top">Breathtaking colors in this shot.  8.</td>', 'Breathtaking colors in this shot.  8.', '2006-09-03 00:01:07.000000', NULL, 1),
(2790555, 386171, 57726, '<td valign="top">Strong photo.  Great color.  Tells a story.  9.</td>', 'Strong photo.  Great color.  Tells a story.  9.', '2006-09-03 00:02:05.000000', NULL, 1),
(2790559, 386912, 57726, '<td valign="top">Great capture.  Great colors.  8.</td>', 'Great capture.  Great colors.  8.', '2006-09-03 00:02:52.000000', NULL, 1),
