(2801411, 387156, 42792, '<td valign="top">Very pretty.  That lacy umbrella is definitely a nice touch.</td>', 'Very pretty.  That lacy umbrella is definitely a nice touch.', '2006-09-05 18:21:22.000000', NULL, 1),
(2801417, 387612, 42792, '<td valign="top">Makes me smile.  Nice clean shot.  Very well done.</td>', 'Makes me smile.  Nice clean shot.  Very well done.', '2006-09-05 18:22:53.000000', NULL, 1),
(2801420, 384492, 22543, '<td valign="top">very nicely done<br/>the palm trees make for very interesting silouettes, and the sunset in the background is very pretty</td>', 'very nicely donethe palm trees make for very interesting silouettes, and the sunset in the background is very pretty', '2006-09-05 18:23:26.000000', NULL, 1),
